window.POTENTIAL_SCREENING = {"revision":1,"reviewedAt":"2026-10-19","horizon":"从2026-10-16报价起，考察未来五年每股价值","title":"先看行业变化，再找利润跃迁","summary":"本轮初筛6家，优先研究PL、ASTS、AUR；目前没有十倍可能性高的公司。","scope":"三个方向各选两家作有限初筛，不是全部上市公司的排名。旧名单不作为本轮起点。","judgmentBasis":"高、中、低及中低是基于商业路径与起始估值的研究判断，不是统计概率。研究优先级表示继续投入研究的价值，不等于上涨把握或买入建议。","profitPrinciple":"股价长期受每股可持续利润或现金流及市场估值影响。收入、利润率、股数和估值可以同时变化，所以十倍股不要求营收也增长十倍。亏损公司不能用负利润作增长倍数；先研究能否形成正的单位利润，再研究规模、融资和每股回报。","historyLesson":"历史十倍股只提供机制线索：新市场、份额提升、经营杠杆、周期反转或估值变化可能共同作用。必须同时寻找失败对照；不能把事后赢家的共同点当作事前成功率，也不能把所有终值固定成30倍PE。","priceBasis":"股价为2026-10-16盘后行情快照，美元计价；市值仅用于初筛量级。不同公司的股本口径单列，未据此输出目标价。","reportPath":"docs/research/potential-screening-2026-10-19.md","quotePath":"data/potential-screening-quotes.json","sectors":[{"id":"interconnect","name":"AI数据互联","verdict":"需求强，当前价格门槛高","change":"AI集群需要芯片之间更快、更省电地交换数据，互联芯片的价值随系统复杂度提升。","profit":"技术复用和单机价值量可放大利润；平台自研、光互联替代和客户议价也会分走收益。","evidence":"NVIDIA已公布Rubin及新一代互联架构；这是行业需求证据，也说明平台自身就是竞争者，不能直接算成CRDO或ALAB的订单。","sources":["nv-rubin","crdo-q","alab-q"]},{"id":"satellite","name":"卫星通信与数据","verdict":"优先比较持续收费能力","change":"把原本无法覆盖的通信和难以持续观测的地表变化变成可购买的服务。","profit":"同一套星座服务更多客户，收入有机会快于固定成本增长；发射、补网和定制交付会消耗现金。","evidence":"Vodafone已设立与AST合作的欧洲服务公司；Planet已有地球观测收入。两个市场不同，不能用一个笼统的“太空市场规模”估值。","sources":["vodafone-sat","pl-q"]},{"id":"autonomy","name":"无人驾驶与配送","verdict":"先货运，后低客单价配送","change":"自动驾驶尝试把反复发生的人工支出转成可复用的软件与设备投入。","profit":"不需要货运量增长十倍：节省部分司机成本、提高车辆利用率，也可能创造新利润。供应商能留下多少才是关键。","evidence":"ATRI报告2025年卡车平均运营成本每英里2.336美元；这不是全部可节省成本。Aurora已有无人货运，Serve则面临配送需求不足。","sources":["atri-cost","aur-day","serv-q"]}],"companies":[{"id":"PL","name":"Planet Labs","market":"us","sector":"satellite","selected":true,"priority":"较高","tenfold":"中低","businessBrief":"运营遥感卫星，向政府与企业出售地球影像、分析和卫星服务。","profitBrief":"影像重复销售、分析增值和固定成本摊薄；定制造星会削弱这种杠杆。","judgment":"业务与付费需求已存在，但利润拐点尚弱；比纯概念更值得深挖，不能把高增长收入直接当高增长利润。","business":"Planet自己造、发射并运营地球观测卫星。政府、农业、林业等客户付钱购买影像、变化监测及相关软件；公司也为政府提供专用卫星服务。它出售的是持续观测和决策信息，收入不只来自卖卫星。","opportunity":"想象力在于把一张张图片变成可反复收费的监测服务。更频繁、更清晰的影像加上分析工具，可能让原先靠人工、低频或昂贵方式完成的工作变成日常采购；AI应用仍需付费转化，推出产品不等于形成新收入。","profitMechanism":"同一份影像可服务多个客户，新增数据订阅有机会摊薄星座和研发成本；如果客户需要更多新造卫星或专用容量，增长也会带来资本开支和折旧。利润能否快于收入增长，取决于这两类业务的比例，而不是先填一个高净利率。","startingValue":"行情市值约48.8亿美元，已是FY2027公司全年收入指引4.30–4.41亿美元的约11倍。这个比较只反映预期门槛，不把市销率当目标估值；若当前股本不变，十倍还意味着约488亿美元股权规模。","capitalBasis":"市值为行情工具口径，未逐项展开全部潜在股份。公司Q2通过ATM售股净筹约1.20亿美元；现金增长包含融资，不能全部归功于经营。","facts":[{"label":"已发生 · FY2027 Q2，截至2026-07-31","text":"收入1.161亿美元，同比增长58%；GAAP毛利率57%，上年同期58%；GAAP净亏损约940万美元。","sources":["pl-q"]},{"label":"公司指引 · 2026-09-03","text":"FY2027收入4.30–4.41亿美元，资本开支1.00–1.15亿美元；这是全年目标，不能把强劲单季直接乘四作为预测。","sources":["pl-q"]}],"check":{"question":"收入增长是否已证明利润率跃升？","answer":"没有。收入增长58%，GAAP毛利率反而略降；亏损收窄是进展，但尚不足以证明数据平台式利润爆发。当前优先级来自可重复销售的机制，而非现有利润率已经兑现。","sources":["pl-q"]},"risks":["政府订单的预算、取消条款和交付节奏可能使收入跳动；合同总额不是当期收入。","专用卫星服务占比上升，可能让收入扩张同时要求更多资本投入。","新股发行会分摊未来利润；高收入增长不保证每股回报。"],"nextQuestion":"下一轮只拆一件事：数据订阅与专用卫星服务各自增加一美元收入，需要多少新增成本和资本？重点找合同责任及分业务毛利，缺少披露就限制利润率假设。","upgrade":"可重复数据服务扩张，同时扣除股权薪酬和维持星座投入后的每股盈利改善，才上调判断。","downgrade":"增长主要靠定制造星、资本开支与收入同步放大，或新增股数吞掉经营改善，则下调。","sources":["pl-q","screen-quotes"],"quote":{"symbol":"PL","priceUsd":13.56,"marketCapUsd":4876095345,"tradeTimeUtc":"2026-10-16T23:59:05Z"}},{"id":"ASTS","name":"AST SpaceMobile","market":"us","sector":"satellite","selected":true,"priority":"较高","tenfold":"中低","businessBrief":"建设能直连普通手机的卫星网络，与移动运营商合作提供覆盖。","profitBrief":"新增付费用户共用星座，持续服务收入有杠杆；建设、补网和分成成本很重。","judgment":"新服务的上限大，但现在主要仍在建设网络。用户付费、容量和资本回报三关必须同时通过，不能因题材大就给高概率。","business":"AST建设太空中的移动通信网络，让普通手机在地面网络覆盖不足的地方连接卫星。移动运营商是重要渠道，最终收入取决于运营商采购、用户使用和双方商业分配；它也有政府项目及地面网关销售。","opportunity":"机会不是让全球手机用户再多十倍，而是让已有手机用户在原本无覆盖的地点也能购买连接服务。Vodafone参与的欧洲合资公司说明渠道正在形成；渠道覆盖人口不等于付费卫星用户。","profitMechanism":"网络建成后，更多付费流量可共用卫星和地面设施，固定成本摊薄可能很快；但单星容量有限，还要承担频谱、运营商分成、卫星寿命及补网成本。只有净服务利润超过这些全生命周期成本，才可能变成股东利润。","startingValue":"行情工具约121.6亿美元市值不能代表全集团经济权益。按8月6日约2.998亿股A类及约0.894亿份B/C对应可交换权益、乘40.66美元，仅作静态量级约158亿美元；尚未计可转债、奖励股及其后变动。十倍需要的价值体量已很大。","capitalBasis":"B/C类股份本身的经济权利与其配对AST LLC权益须合并理解；这里按披露的1:1交换关系作量级比较，不把B/C股份再重复计一次。未作完全摊薄目标价。","facts":[{"label":"已发生 · 2026 Q2","text":"收入3152万美元，其中产品2442.8万美元、服务709.2万美元；不能把总收入都说成手机用户持续订阅。","sources":["asts-q"]},{"label":"已发生 · 2026上半年","text":"经营现金净流出1.452亿美元，购置物业设备8.592亿美元；6月底现金及等价物22.883亿美元，另有受限资金。网络建设明显先于服务收入。","sources":["asts-q"]}],"check":{"question":"已有营收能证明直连手机的商业模式跑通吗？","answer":"不能。Q2产品占收入约78%，服务收入也不能全部认定为消费者持续付费。已有运营商渠道和技术进展，但尚缺可用于推算成熟利润的付费用户、实收单价、每星可售容量和补网成本组合。","sources":["asts-q","vodafone-sat"]},"risks":["发射失败、建设延误或可用容量不足，会同时推迟收费并增加资本需求。","运营商议价、其他卫星网络竞争可能压缩实收单价和分成。","可转债、股权融资及存续网络维护可能显著稀释每股回报。"],"nextQuestion":"下一轮把每星可售容量、实际付费覆盖、运营商分成和补网成本放在一起，判断星座成熟后能留下多少现金，而不是拿全球用户数直接乘套餐价格。","upgrade":"连续商业服务披露出可重复的实收收入与容量利用率，且补网后的回报仍有吸引力，才上调。","downgrade":"建设持续超支、服务收费推迟，或容量和实收单价无法覆盖全生命周期投入，则下调。","sources":["asts-q","vodafone-sat","screen-quotes"],"quote":{"symbol":"ASTS","priceUsd":40.66,"marketCapUsd":12159847177,"tradeTimeUtc":"2026-10-16T23:46:28Z"}},{"id":"AUR","name":"Aurora Innovation","market":"us","sector":"autonomy","selected":true,"priority":"中","tenfold":"中低","businessBrief":"开发无人驾驶系统，先用于干线重卡，向货运客户提供运输或驾驶服务。","profitBrief":"节省部分人工并提高车辆利用率，尝试按持续使用收费；远程协助和硬件不能忽略。","judgment":"成本替代逻辑比低客单价配送更强，已开始无人商业货运；但规模与软件式毛利仍是目标，近百亿美元起点不便宜。","business":"Aurora把传感器、计算硬件和自动驾驶软件装到重卡上。当前运输服务由货运客户付费；计划进一步让客户拥有车辆、购买Driver as a Service驾驶服务，商业模式从提供运力向持续收取驾驶服务费发展。","opportunity":"同样一车货，若减少驾驶人工并延长可运营时间，就能创造价值，不必等待整个货运行业增长十倍。干线长途运行的经济价值更集中；城市配送每单收费低、环境复杂，不能直接套用相同盈利假设。","profitMechanism":"若车辆主要由客户持有，Aurora可让同一套驾驶软件服务更多卡车，研发成本被摊薄。但软件之外仍有硬件、运维、远程支持及保险责任。客户愿付的服务费不能超过真实节省的成本，节省额也不会全部归Aurora。","startingValue":"行情市值约95.9亿美元。即使2030年数十亿美元收入的管理层愿景兑现，也仍需检验可持续利润与股本，不能把它自动等同于从当前起点涨十倍。","capitalBasis":"6月底公司披露现金及短期投资近12亿美元。规模化前仍需研发与车队投入；本轮没有用账面现金除以单季亏损推算精确续航，也没有假设不再增发。","facts":[{"label":"公司运营披露 · 2026-09-23","text":"商业启动以来无人行驶超过50万英里；部分客户车辆折算年化运行超过22.5万英里。年化运行速度不是已经跑满一年的结果。","sources":["aur-day"]},{"label":"公司目标与意向 · 非已交付订单","text":"2030年超过3万辆、数十亿美元收入及DaaS软件式毛利均为公司愿景；Hirschbach的500辆计划涉及非约束性MOU，不能当确定收入。","sources":["aur-day"]}],"check":{"question":"省掉司机成本就一定能赚到软件利润吗？","answer":"不一定。ATRI的2.336美元每英里是行业全部运营成本，燃料、车辆和维护并不会因无人驾驶消失。Aurora的硬件降本和高利用率支持研究方向，但DaaS真实收费与支持成本尚不足以证明成熟净利率。","sources":["atri-cost","aur-q","aur-day"]},"risks":["扩大路线和复杂天气适用范围可能比现有路线困难，安全事件会影响部署。","高利用率可能增加维护和折旧；车队运力闲置也会削弱节省额。","客户意向、量产能力与真正投入收费运行的车辆数量之间仍有距离。"],"nextQuestion":"下一轮只检验客户每英里的总成本：驾驶服务费加硬件、远程支持、保险与维护后，是否仍明显优于人工，且Aurora能留下正贡献利润。","upgrade":"DaaS约束性合同与实收收费形成规模，客户总成本下降，同时Aurora每英里贡献利润转正，才上调。","downgrade":"部署主要靠自持车队和补贴，或远程支持、事故及维护费用抵消人工节省，则下调。","sources":["aur-q","aur-day","atri-cost","screen-quotes"],"quote":{"symbol":"AUR","priceUsd":4.855,"marketCapUsd":9593480000,"tradeTimeUtc":"2026-10-16T23:27:11Z"}},{"id":"CRDO","name":"Credo Technology","market":"us","sector":"interconnect","selected":false,"priority":"低","tenfold":"低","businessBrief":"为数据中心提供高速连接芯片及有源电缆，帮助服务器交换数据。","profitBrief":"高速升级增加单机价值，研发复用放大利润；现有毛利已高，不能无限外推。","judgment":"行业和利润增长真实，但约330亿美元起点已不小，毛利率也不低；本轮不列入优先深挖的十倍候选。","business":"Credo出售用于铜缆和光连接的高速互联产品，让服务器、交换设备之间的数据传输更快、更可靠，并降低能耗。客户购买的是解决数据传输瓶颈的部件与连接方案，公司不是生产AI模型或GPU。","opportunity":"AI集群扩大与连接速度升级，可以增加连接数量和每条链路的技术价值。即使服务器数量没有十倍增长，产品组合和份额变化也可能推动利润；但铜与光方案的切换会改变受益产品。","profitMechanism":"芯片设计与知识产权能够复用，销售扩张可摊薄研发费用。已有64.5%的GAAP毛利率意味着利润想象力不能靠毛利率任意倍增；更应看营业费用、客户集中、竞争降价和股权薪酬。","startingValue":"行情市值约329.9亿美元；十倍对应约3300亿美元的静态股权规模，还未考虑新增股份。盈利不错并不足以证明这个终点合理，当前价格对长期增长的要求已经很高。","capitalBasis":"用GAAP营业利润观察经营，不用剔除大量股权薪酬后的利润替代股东成本；行情市值不作为完全摊薄估值。","facts":[{"label":"已发生 · FY2027 Q1，截至2026-08-01","text":"收入4.790亿美元，同比增长114.7%；GAAP毛利率64.5%，营业利润1.207亿美元。","sources":["crdo-q"]},{"label":"利润约束","text":"GAAP营业利润低于上季1.558亿美元，尽管收入环比增长9.6%；不能用收入加速直接替代利润增速。","sources":["crdo-q"]}],"check":{"question":"好行业和高增长是否足以支持当前起点十倍？","answer":"不够。当前已有较高毛利和较大股权规模，仍需多年需求、份额和每股利润持续扩张；本轮相对优先级低，不为补满名单而继续堆报告。","sources":["crdo-q","screen-quotes"]},"risks":["大客户自研、替代方案和价格谈判可能压缩利润。","产品架构变化和并购费用可能使营收增长与每股利润脱节。"],"nextQuestion":"本轮不进入深入研究；若起始估值显著下降，或新产品证明更大的可持续利润来源，再重新筛选。","upgrade":"出现可验证的新利润来源，或价格下降明显降低回报门槛。","downgrade":"收入增长伴随经营利润、每股利润或现金创造持续走弱。","sources":["crdo-q","nv-rubin","screen-quotes"],"quote":{"symbol":"CRDO","priceUsd":169.7,"marketCapUsd":32985946600,"tradeTimeUtc":"2026-10-16T23:58:29Z"}},{"id":"ALAB","name":"Astera Labs","market":"us","sector":"interconnect","selected":false,"priority":"低","tenfold":"低","businessBrief":"提供AI服务器互联芯片，连接加速器、内存与网络，向交换芯片扩展。","profitBrief":"从单个信号器件扩展到系统互联，提高产品价值；高起始估值限制股价空间。","judgment":"产品扩张值得关注，但约524亿美元起点、73.3%毛利率使十倍需要极强持续兑现；本轮不优先。","business":"Astera Labs设计服务器内部及机架之间的连接芯片，包括信号调理、内存连接和Scorpio交换产品，并配套管理软件。云和AI设备厂商购买这些组件，以减少高速数据交换的瓶颈和故障。","opportunity":"从卖一段链路的器件到承接更大的互联系统，可能让每个机架需要的Astera产品价值上升。新架构与定制芯片是扩展方向；发布参考设计和获得设计采用，不等于已经形成大额收入。","profitMechanism":"产品平台与研发复用可能让营业利润快于收入增长。但当前GAAP毛利率已达73.3%，不能再靠毛利率数倍提升解释十倍回报；营业费用、竞争份额、股权薪酬和税收因素都必须保留。","startingValue":"行情市值约524.0亿美元。即使新产品高速增长，十倍仍意味着约5240亿美元的静态股权规模；本轮没有足够理由把这类终点当高可能性。","capitalBasis":"本季GAAP净利含约5026万美元所得税收益，因此不把净利1.531亿美元直接年化成可持续利润；优先观察营业利润。","facts":[{"label":"已发生 · 2026 Q2","text":"收入3.924亿美元，同比增长104%；GAAP毛利率73.3%，营业利润8925万美元，营业利润率22.7%。","sources":["alab-q"]},{"label":"公司指引 · 非已实现","text":"公司预计Q3收入5.40–5.60亿美元，Scorpio交换产品推动增长；预测中的产品放量仍需实际收入检验。","sources":["alab-q"]}],"check":{"question":"利润率提高能否单独解释十倍？","answer":"营业利润率仍可能改善，但毛利率起点已经很高。更大产品范围、持续高增和合理购买价格必须共同成立，不能只把终点净利率或PE往上调。","sources":["alab-q","screen-quotes"]},"risks":["平台厂商自研与竞争产品可能影响份额和价格。","新产品结构变化可能增加研发支出；一次性税收收益会夸大表观净利。"],"nextQuestion":"本轮不进入深入研究；等待新产品利润兑现或价格变化，再重新评估每股回报门槛。","upgrade":"新增互联产品形成可持续的每股利润增长，且起始估值留出足够空间。","downgrade":"产品放量弱于预期，或费用与稀释使每股利润无法跟上收入。","sources":["alab-q","nv-rubin","screen-quotes"],"quote":{"symbol":"ALAB","priceUsd":285.82,"marketCapUsd":52402238800,"tradeTimeUtc":"2026-10-16T23:38:34Z"}},{"id":"SERV","name":"Serve Robotics","market":"us","sector":"autonomy","selected":false,"priority":"低","tenfold":"低","businessBrief":"运营配送机器人并提供相关软件，向配送合作方、广告及医院客户收费。","profitBrief":"提高机器人订单密度、摊薄远程支持与折旧；现在需求和毛利均未过关。","judgment":"小市值提供价格弹性，却不能抵消需求不足与毛亏损。相对无人重卡，目前更缺可重复盈利的证据。","business":"Serve让小型机器人执行末端配送，也有医院场景及软件业务。收费来源包括车队服务、软件与广告。它的价值应是让每次配送的总成本下降，不能只比较机器人购买价格和人的工资。","opportunity":"高密度、短距离、重复路线可能适合机器人；同一台设备多跑订单，可以摊薄硬件和运维成本。但每单价值有限，等待、空驶和远程介入会消耗节省额，行业不会因为机器变便宜就自动出现十倍利润空间。","profitMechanism":"利润取决于每单实收减去运维、远程支持、折旧等成本，再扣研发和管理费用。广告和软件可改善组合，但如果配送量不足或需要补贴，机器人数量扩大也可能只是扩大亏损。","startingValue":"3.23美元乘公司披露的6月底约8600万已发行股，静态约2.78亿美元；未计其后变动和潜在稀释。起点小，但不是已找到便宜的盈利资产。","capitalBasis":"6月底现金及有价证券2.404亿美元，不代表净清算价值，也不能忽略后续烧钱和承诺。行情商市值与披露股数折算不一致，因此明确采用日期分开的股价×股数。","facts":[{"label":"已发生 · 2026 Q2","text":"收入323.8万美元，收入成本1201.7万美元，毛亏损877.9万美元；平均日活跃机器人792台，低于Q1的812台，且包括室内外车队。","sources":["serv-q"]},{"label":"公司下调指引 · 2026-08-06","text":"全年收入改为900–1000万美元，原因包括Uber Eats配送需求低于预期；不能将合作平台规模直接当成Serve订单。","sources":["serv-q"]}],"check":{"question":"机器人便宜、小市值，就更容易十倍吗？","answer":"小市值只降低所需总价值量级。眼下更直接的反证是需求下修、活跃设备环比下降和显著毛亏损；在单位经济改善前，继续外推机器人数没有说服力。","sources":["serv-q"]},"risks":["平台合作不保证订单密度，低利用率会让折旧和支持成本难以摊薄。","现金消耗与融资可能让公司规模增长却每股价值不增长。"],"nextQuestion":"本轮不进入深入研究；只有配送需求回升、每单经济性和毛利持续改善，才重新初筛。","upgrade":"可重复的订单密度与单位贡献利润改善，而非只增加部署数量。","downgrade":"继续下调需求、靠融资维持低利用率扩张。","sources":["serv-q","screen-quotes"],"quote":{"symbol":"SERV","priceUsd":3.23,"marketCapUsd":259403183,"tradeTimeUtc":"2026-10-16T22:59:22Z"}}],"sources":[{"id":"crdo-q","title":"Credo FY2027 Q1业绩公告","url":"https://investors.credosemi.com/news-events/news/news-details/2026/Credo-Technology-Group-Holding-Ltd-Reports-First-Quarter-of-Fiscal-Year-2027-Financial-Results/default.aspx","publishedAt":"2026-09-01","locator":"GAAP财务亮点及季度营业利润表；截至2026-08-01"},{"id":"alab-q","title":"Astera Labs 2026 Q2业绩公告","url":"https://ir.asteralabs.com/news-releases/news-release-details/astera-labs-reports-second-quarter-2026-financial-results","publishedAt":"2026-08-04","locator":"GAAP结果、所得税收益、Q3指引及产品更新"},{"id":"pl-q","title":"Planet FY2027 Q2业绩公告","url":"https://investors.planet.com/news/news-details/2026/Planet-Reports-Financial-Results-for-Second-Quarter-of-Fiscal-Year-2027/default.aspx","publishedAt":"2026-09-03","locator":"截至2026-07-31；GAAP利润、FY27指引、ATM融资和业务介绍"},{"id":"asts-q","title":"AST SpaceMobile 2026 Q2 Form 10-Q","url":"https://app.quotemedia.com/data/downloadFiling?cdn=97b0f90b3039b64b39c17ee3c872f664&companyName=AST+SpaceMobile+Inc.&dateFiled=2026-08-10&formType=10-Q&ref=320259077&symbol=ASTS&type=PDF&webmasterId=102691","publishedAt":"2026-08-10","locator":"PDF第1页股数、第3–4页现金及营收、第8页现金流、第19页LLC权益交换"},{"id":"aur-q","title":"Aurora 2026 Q2业绩公告","url":"https://ir.aurora.tech/news-events/press-releases/detail/147/aurora-announces-second-quarter-2026-results","publishedAt":"2026-07-29","locator":"二代硬件、商业客户、现金和短期投资；硬件降本为预期"},{"id":"aur-day","title":"Aurora 2026投资者日公告（8-K附件）","url":"https://ir.aurora.tech/sec-filings/all-sec-filings/content/0001828108-26-000082/businesswire-aurora2026ana.htm","publishedAt":"2026-09-23","locator":"实际运营里程、2030愿景及风险段落中的non-binding MOU"},{"id":"serv-q","title":"Serve Robotics 2026 Q2业绩公告","url":"https://investors.serverobotics.com/news-releases/news-release-details/serve-robotics-announces-second-quarter-2026-results","publishedAt":"2026-08-06","locator":"下调收入指引、日活机器人、分项收入与GAAP毛亏损、股数"},{"id":"nv-rubin","title":"NVIDIA Rubin量产与互联架构公告","url":"https://nvidianews.nvidia.com/news/vera-rubin-full-production-agentic-ai-factory","publishedAt":"2026-05-31","locator":"Rubin、NVLink与Spectrum-X光互联；不构成指定供应商的订单证明"},{"id":"vodafone-sat","title":"Vodafone：Satellite Connect Europe成立","url":"https://www.vodafone.com/news/newsroom/technology/satellite-connect-europe-launches-direct-to-device-broadband-satellite-connectivity","publishedAt":"2026-02-27","locator":"与AST合资、面向移动运营商的服务和地面站投资"},{"id":"atri-cost","title":"ATRI 2026卡车运营成本研究摘要","url":"https://truckingresearch.org/2026/07/new-atri-report-details-accelerating-costs-and-low-profitability-despite-cuts/","publishedAt":"2026-07-15","locator":"2025年行业全部运营成本2.336美元/英里；不能等同可节省人工成本"},{"id":"screen-quotes","title":"2026-10-16盘后行情快照与口径","url":"data/potential-screening-quotes.json","publishedAt":"2026-10-19","locator":"web.finance检索记录；保留价格、市值和UTC交易时间"}]};
